// Expense Guard — a multi-company expense-review agent. Reviews one expense submission
// (company_id + receipt + claimed amount + category) against that company's written
// policy and returns a structured decision: approve / flag_for_review / reject.
//
// Schema-output agent WITH tools: it emits the decision through `outputSchema`, and
// drives to that decision by calling search_policy (fetch the company policy) and
// validate_expense (sanity-check the submission). Eve binds `model` statically at build
// time — there is no runtime model override.
import { defineAgent } from "eve";
import { ExpenseDecisionSchema } from "./lib/expense.schema.js";

export default defineAgent({
  model: "anthropic/claude-opus-4-1-20250805",
  // Dated Anthropic ids aren't in the Gateway model catalog, so pin the window to skip
  // the lookup diagnostic.
  modelContextWindowTokens: 200_000,
  outputSchema: ExpenseDecisionSchema,
});

input.content:
export const meta = {
  name: 'orchestrator',
  description: 'Expense Guard orchestrator: plan → investigate → adversarially verify → execute → report, driven by the instruction passed in args',
  whenToUse: 'Invoke with args = { prompt: "<instruction>" } whenever the user sends an ORCHESTRATOR instruction for this repo (via /orchestrator or a prompt addressed to ORCHESTRATOR)',
  phases: [
    { title: 'Plan', detail: 'interpret the instruction into concrete tasks' },
    { title: 'Investigate', detail: 'parallel research agents over the repo' },
    { title: 'Verify', detail: 'adversarial refutation of each finding' },
    { title: 'Execute', detail: 'apply changes sequentially, prove with evals' },
    { title: 'Report', detail: 'synthesize the outcome' },
  ],
}

const PROMPT = typeof args === 'string' ? args : (args && args.prompt) || ''
if (!PROMPT.trim()) {
  throw new Error('orchestrator requires args = { prompt: "<instruction>" } (or a plain string)')
}

// Shared repo briefing every agent receives. Facts only — agents form their own hypotheses.
const REPO = `
Repo: /Users/jorgenino/Documents/expense-guard-challenge — "Expense Guard", a take-home challenge.
A multi-tenant expense-review agent built on Eve 0.11.7 (Vercel agent framework), Bun, TypeScript,
ai-sdk. Reviews one submission (company_id, OCR receipt, amount, category) against that company's
policy and returns approve / flag_for_review / reject via outputSchema.

Layout:
- README.md — the challenge brief (task, ground rules, deliverables). Read it first.
- agent/agent.ts — defineAgent: model anthropic/claude-opus-4-1-20250805, outputSchema
- agent/instructions/system.ts, agent/lib/build-instructions.ts — prompt assembly
- agent/lib/ — policy-store.ts, policies.ts, request-context.ts, expense.schema.ts
- agent/tools/ — search_policy, validate_expense, plus bash, read_file, write_file, glob, grep,
  web_search, web_fetch, todo, ask_question
- agent/channels/eve.ts — HTTP channel (POST /eve/v1/review); agent/hooks/usage-log.ts
- agent/sandbox.ts — backend pinned to justbash for macOS (do not touch, per README)
- evals/ — evals.config.ts, approve-valid.eval.ts, policy-citation.eval.ts
- fixtures/ — request.json, valid.json, ambiguous.json, illegible.json, cross-company.json

Commands: bun install; bunx eve build; bunx eve dev; bunx eve eval. Needs AI_GATEWAY_API_KEY in .env.

Challenge ground rules that bind every change:
- The bugs span correctness, security (tenant isolation!), cost, and maintainability.
- Production-quality code, no dead code, no unexplained magic numbers.
- Never fabricate data — report only what was actually run and observed.
- Every fix should be backed by an eval that would have caught the bug.
- Deliverables live at repo root: FINDINGS.md, BOUNDARIES.md.
`.trim()

const PLAN_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['mode', 'summary', 'tasks'],
  properties: {
    mode: {
      type: 'string',
      enum: ['investigate', 'implement'],
      description: 'investigate = research/answer only, no file changes. implement = changes to files are part of the instruction.',
    },
    summary: { type: 'string', description: 'One-paragraph interpretation of the instruction' },
    tasks: {
      type: 'array',
      maxItems: 8,
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['id', 'title', 'kind', 'prompt'],
        properties: {
          id: { type: 'string', description: 'short kebab-case id' },
          title: { type: 'string' },
          kind: { type: 'string', enum: ['research', 'code', 'docs'] },
          prompt: { type: 'string', description: 'Self-contained instructions for the agent doing this task' },
          files: { type: 'array', items: { type: 'string' }, description: 'files this task centers on' },
        },
      },
    },
  },
}

const FINDINGS_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['findings'],
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['title', 'category', 'file', 'evidence', 'claim'],
        properties: {
          title: { type: 'string' },
          category: { type: 'string', enum: ['correctness', 'security', 'cost', 'maintainability', 'other'] },
          file: { type: 'string', description: 'file:line the finding anchors to' },
          evidence: { type: 'string', description: 'what was actually read/run that supports this' },
          claim: { type: 'string', description: 'the precise defect claim, falsifiable' },
          suggested_fix: { type: 'string' },
        },
      },
    },
    notes: { type: 'string', description: 'anything checked and found clean, or left uninspected' },
  },
}

const VERDICT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['refuted', 'reasoning'],
  properties: {
    refuted: { type: 'boolean', description: 'true if the claim does not hold as stated' },
    reasoning: { type: 'string' },
    correction: { type: 'string', description: 'if partially wrong, the corrected claim' },
  },
}

const EXEC_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['status', 'changes', 'verification'],
  properties: {
    status: { type: 'string', enum: ['done', 'partial', 'blocked'] },
    changes: { type: 'array', items: { type: 'string' }, description: 'files touched and what changed in each' },
    verification: { type: 'string', description: 'exact commands run (typecheck/evals) and their real output summary; say honestly if nothing was run' },
    followups: { type: 'array', items: { type: 'string' } },
  },
}

// ---- Plan -------------------------------------------------------------------
phase('Plan')
const plan = await agent(
  `${REPO}

You are the planning stage of a multi-agent orchestration for this repo.

The user's instruction:
<instruction>
${PROMPT}
</instruction>

Read README.md and skim whatever files you need to interpret the instruction precisely.
Decompose it into at most 8 self-contained tasks for downstream agents:
- 'research' tasks investigate/diagnose (read-only) — prefer 2-4 of these with non-overlapping scopes
  (e.g. by concern: tenant isolation & tool surface / prompt & schema correctness / cost & model
  choice / evals & fixtures) unless the instruction is narrower.
- 'code' tasks change source or evals; 'docs' tasks write markdown deliverables. Emit these ONLY if
  the instruction actually asks for changes; they run after research, sequentially, and will
  receive the verified findings as input, so their prompts should say what to do with them.
Set mode='investigate' when the instruction is a question/analysis; mode='implement' when it asks
for changes. Each task prompt must be self-contained — the agent sees nothing else but the repo
briefing and (for code/docs tasks) the verified findings.`,
  { label: 'plan', schema: PLAN_SCHEMA },
)
log(`Plan (${plan.mode}): ${plan.tasks.map((t) => t.id).join(', ')}`)

const MAX_RESEARCH = 4
const MAX_FINDINGS_PER_TASK = 4
const researchTasks = plan.tasks.filter((t) => t.kind === 'research').slice(0, MAX_RESEARCH)
if (plan.tasks.filter((t) => t.kind === 'research').length > MAX_RESEARCH) {
  log(`capped research tasks at ${MAX_RESEARCH} — dropped: ${plan.tasks.filter((t) => t.kind === 'research').slice(MAX_RESEARCH).map((t) => t.id).join(', ')}`)
}

// ---- Investigate → Verify (pipeline: each task's findings verify as they land) ----
const verifiedPerTask = await pipeline(
  researchTasks,
  (t) =>
    agent(
      `${REPO}

You are a read-only investigator. Do NOT modify any files.

Your task (id: ${t.id}): ${t.title}
${t.prompt}
${t.files && t.files.length ? `Focus files: ${t.files.join(', ')}` : ''}

Ground every finding in evidence you actually gathered (file+line you read, command you ran and
its output). A falsifiable claim with weak evidence is worth reporting; a vague vibe is not.
Also report what you checked and found clean in 'notes'.`,
      { label: `investigate:${t.id}`, phase: 'Investigate', schema: FINDINGS_SCHEMA },
    ),
  async (res, t) => {
    if (!res) return { task: t.id, findings: [], notes: 'investigator failed' }
    const kept = res.findings.slice(0, MAX_FINDINGS_PER_TASK)
    if (res.findings.length > kept.length) {
      log(`${t.id}: verifying top ${kept.length} of ${res.findings.length} findings`)
    }
    const judged = await parallel(
      kept.map((f) => () =>
        agent(
          `${REPO}

You are an adversarial verifier. Try hard to REFUTE this claim by reading the actual code
(read-only — modify nothing). Default to refuted=true if the evidence does not hold up.

Claim (from task ${t.id}, anchored at ${f.file}):
${f.claim}

Stated evidence: ${f.evidence}
Suggested fix: ${f.suggested_fix || '(none)'}`,
          { label: `verify:${f.title.slice(0, 40)}`, phase: 'Verify', schema: VERDICT_SCHEMA },
        ).then((v) => ({ ...f, task: t.id, verdict: v })),
      ),
    )
    return {
      task: t.id,
      notes: res.notes || '',
      findings: judged.filter(Boolean).filter((j) => j.verdict && !j.verdict.refuted),
      refuted: judged.filter(Boolean).filter((j) => j.verdict && j.verdict.refuted).map((j) => ({ title: j.title, reasoning: j.verdict.reasoning })),
    }
  },
)

const taskResults = verifiedPerTask.filter(Boolean)
const confirmed = taskResults.flatMap((r) => r.findings)
log(`${confirmed.length} findings survived adversarial verification`)

// ---- Execute (only when the instruction asks for changes; sequential to avoid conflicts) ----
const changeTasks = plan.mode === 'implement' ? plan.tasks.filter((t) => t.kind === 'code' || t.kind === 'docs') : []
const executions = []
phase('Execute')
for (const t of changeTasks) {
  const confirmedBlock = confirmed.length
    ? `Verified findings from the investigation stage (use the ones relevant to your task):
${JSON.stringify(confirmed, null, 2)}`
    : 'No verified findings were produced by the investigation stage.'
  const result = await agent(
    `${REPO}

You are an implementation agent working directly in the repo. Ship production-quality changes.

Your task (id: ${t.id}): ${t.title}
${t.prompt}
${t.files && t.files.length ? `Focus files: ${t.files.join(', ')}` : ''}

${confirmedBlock}

Rules:
- Every behavioral fix needs an eval (evals/*.eval.ts) that would have caught the bug.
- Run what you can to verify (bunx tsc --noEmit, bunx eve build, bunx eve eval if a key is
  configured) and report the REAL results — never claim verification you did not run.
- Do not touch agent/sandbox.ts. Do not commit; leave changes in the working tree.`,
    { label: `execute:${t.id}`, phase: 'Execute', schema: EXEC_SCHEMA },
  )
  executions.push({ task: t.id, title: t.title, result })
  if (result) log(`${t.id}: ${result.status} — ${result.changes.length} file(s) changed`)
}

// ---- Report -----------------------------------------------------------------
phase('Report')
const report = await agent(
  `${REPO}

You are the synthesis stage. Write the final report for this orchestration run, in markdown,
for the user who sent the instruction. Lead with the outcome. Be direct and honest — include
refuted findings briefly (so they aren't re-investigated) and anything left undone.

Instruction: ${PROMPT}

Plan summary: ${plan.summary}

Per-task investigation results (findings already adversarially verified):
${JSON.stringify(taskResults, null, 2)}

Execution results:
${JSON.stringify(executions, null, 2)}

Return ONLY the markdown report.`,
  { label: 'report', phase: 'Report' },
)

return {
  mode: plan.mode,
  instruction: PROMPT,
  confirmedFindings: confirmed,
  executions,
  report,
}

