input.content:
export const meta = {
  name: 'implement-challenge',
  description: 'Expense Guard phase 2: fix verified findings, write evals, produce FINDINGS.md + BOUNDARIES.md, adversarially review the diff, run the final gate',
  whenToUse: 'Run after the orchestrator investigation phase, with args = { findings: [...], refuted: [...], notes: [...] } from its result',
  phases: [
    { title: 'Fix', detail: 'one agent per finding category, sequential, eval-backed' },
    { title: 'Docs', detail: 'FINDINGS.md and BOUNDARIES.md' },
    { title: 'Review', detail: 'adversarial review of the full diff, then corrections' },
    { title: 'Gate', detail: 'typecheck, build, eval suite — real output only' },
    { title: 'Report' },
  ],
}

const findings = (args && args.findings) || []
const refuted = (args && args.refuted) || []
const investigationNotes = (args && args.notes) || []
if (!findings.length) {
  throw new Error('implement-challenge requires args.findings — the confirmedFindings array from the orchestrator investigation run')
}

const REPO = `
Repo: /Users/jorgenino/Documents/expense-guard-challenge — "Expense Guard", a take-home challenge.
A multi-tenant expense-review agent built on Eve 0.11.7 (Vercel agent framework), Bun, TypeScript,
ai-sdk. Reviews one submission (company_id, OCR receipt, amount, category) against that company's
policy and returns approve / flag_for_review / reject via outputSchema. See CLAUDE.md for the map
and README.md for the full brief.

Commands: bun install; bunx tsc --noEmit; bunx eve build; bunx eve dev; bunx eve eval
(eval/dev need AI_GATEWAY_API_KEY in .env — if it is missing, say so instead of pretending).

Ground rules that bind every change:
- Tenant isolation is sacred — one company's review must never see another company's policy/data.
- Production-quality code: clear naming, no dead code, no unexplained magic numbers.
- Never fabricate data — report only what you actually ran and observed.
