const notes=[];const unverified=[];
const confirmedTitles=new Set(findings.map(f=>f.title));
for(const e of journal){
  const r=e.result??e.value??e.output; const label=e.label||e.opts?.label||"";
  if(!r||typeof r!=="object"||!Array.isArray(r.findings))continue;
  if(r.notes)notes.push({investigator:label,notes:r.notes});
